{
  "id": "loc_01",
  "name": "青玄大陆",
  "kind": "continent",
  "entryConditions": [
    "本土生灵无需出入境凭证；外来修士通常经虚海航线入港，由沿岸政权验籍征税。",
    "跨海古阵只作航向定位、接引入港和短程接驳，依附实体飞舟航程，不能省略跨海时间或打开太古界门。"
  ],
  "status": "proposed"
}

{
  "id": "loc_03",
  "name": "赤霄大陆",
  "kind": "continent",
  "entryConditions": [
    "需修持抗火法门或佩戴避火灵符",
    "玄府境以下需避开地火煞气喷发期"
  ],
  "status": "proposed"
}

